<style>.category-total{background:var(--surface-2)}.subcategory-row td:first-child{padding-left:30px;color:var(--ink-soft)}.comparison-strip{display:grid;grid-template-columns:repeat(5,minmax(130px,1fr));gap:8px;margin:0 0 14px}.comparison-strip>div{background:var(--surface-2);border:1px solid var(--line);border-radius:8px;padding:10px 12px}.comparison-strip span{display:block;color:var(--ink-dim);font-size:10.5px;font-weight:600;margin-bottom:4px}.comparison-strip strong{display:block;font-size:13px;font-variant-numeric:tabular-nums}.over-budget{color:var(--danger)!important}.phase-summary{display:flex;justify-content:space-between;gap:18px;align-items:center;cursor:pointer;list-style:none}.phase-summary::-webkit-details-marker{display:none}.phase-summary span{display:flex;flex-direction:column;gap:3px}.phase-summary span:last-child{color:var(--ink-dim);font-size:11px;text-align:right}.phase-summary small{color:var(--ink-dim);font-weight:400}.pm-phase[open] .phase-summary{padding-bottom:14px;border-bottom:1px solid var(--line);margin-bottom:16px}.phase-body{min-width:0}@media(max-width:900px){.comparison-strip{grid-template-columns:repeat(2,1fr)}.phase-summary{align-items:flex-start}.phase-summary span:last-child{text-align:left}}</style>
<script>(()=>{const tabs=document.getElementById('pmProjectTabs');if(!tabs)return;const groups={overview:[],phases:Array.from(document.querySelectorAll('.main>details.pm-phase')),requests:[]};document.querySelectorAll('.main>section').forEach(section=>{const heading=section.querySelector('h3')?.textContent.trim()||'';if(heading.startsWith('Site Requests')||heading.startsWith('Budget Versions'))groups.requests.push(section);else groups.overview.push(section)});const show=name=>{Object.values(groups).flat().forEach(element=>element.hidden=true);(groups[name]||groups.overview).forEach(element=>element.hidden=false);tabs.querySelectorAll('button').forEach(button=>{button.classList.toggle('btn-primary',button.dataset.projectView===name);button.classList.toggle('btn-ghost',button.dataset.projectView!==name)});history.replaceState(null,'','#'+name)};tabs.addEventListener('click',event=>{const button=event.target.closest('[data-project-view]');if(button)show(button.dataset.projectView)});show(location.hash.slice(1)||'overview')})();</script>
@endsection
